import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ShapeUtilities_equal_TriageGen2Test {









    @Test
    public void testEqual_IdenticalPaths() {
        GeneralPath p1 = new GeneralPath(PathIterator.WIND_NON_ZERO);
        p1.moveTo(10.0, 10.0);
        p1.lineTo(20.0, 20.0);
        p1.closePath();

        GeneralPath p2 = new GeneralPath(PathIterator.WIND_NON_ZERO);
        p2.moveTo(10.0, 10.0);
        p2.lineTo(20.0, 20.0);
        p2.closePath();

        assertTrue(ShapeUtilities.equal(p1, p2));
    }








}

